compile.workshop:
variables {
    global:
        0: reserved
        1: first
        2: explicit
        3: next
}

subroutines {
    0: helper
}

rule ("[Source] renamed helper") {
    event {
        Subroutine;
        helper;
    }
    actions {
        Set Global Variable(first, 1);
    }
}

rule ("[Source] joined") {
    event {
        Player Joined Match;
        Team 1;
        Slot 2;
    }
    actions {
        Call Subroutine(helper);
    }
}

